package org.marketreview.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
import java.lang.ref.WeakReference;
import java.util.*;
import java.time.Instant;
import static org.marketreview.nativeapp.WatchlistWorkspaceModel.*;
import static org.marketreview.nativeapp.UnifiedBackup.*;
/** Internal subpage. Host binds a serialized worker and delivers completion on its UI thread. */
public final class UnifiedBackupScreen extends LinearLayout {
 public interface Done {void finish(JSONObject value,Exception error);}
 public interface Pick {void run()throws Exception;}
 public interface Export {void receive(byte[] bytes,JSONObject summary)throws Exception;}
 final Coordinator coordinator;final UnifiedBackupAsyncLane lane;final UnifiedBackupAsyncLane.Runner runner;final Pick picker;final Export export;
 final List<CheckBox> choices=new ArrayList<>();final Map<String,Boolean> exportable=new HashMap<>();final Map<String,String> names=new HashMap<>();
 final LinearLayout scopePanel,secondaryActions,primaryActions,actionDock;
 final Button scopeToggle,notesToggle,otherActionsToggle;final TextView stage;
 final List<TextView> scopeNotes=new ArrayList<>();boolean scopeExpanded=true,notesExpanded=false,otherActionsExpanded=false;
 final TextView details;final CheckBox ack;final Button generate,open,preview,cancel,begin,next,stop,reread;Button previousText,nextText;String fullText="";int textOffset=0;
 JSONObject bundle=new JSONObject(),plan=new JSONObject();boolean busy=false,started=false,canContinue=false,closed=false,writing=false,active=true;
 interface Result {void accept(JSONObject v)throws Exception;}
 Runnable onInvalidate=()->{};Runnable onPresentationChanged=()->{};
 public UnifiedBackupScreen(Context context,Coordinator coordinator,UnifiedBackupAsyncLane lane,Pick picker,Export export)throws Exception{
  super(context);this.coordinator=coordinator;this.lane=lane;this.runner=lane.runner();this.picker=picker;this.export=export;setOrientation(VERTICAL);setPadding(0,dp(4),0,dp(8));setTag("unifiedBackupScreen");
  stage=new TextView(context);stage.setTextSize(16);stage.setTag("backupStage");addView(stage);
  scopeToggle=button("选择范围","toggleBackupScope");addView(scopeToggle,new LayoutParams(-1,-2));scopeToggle.setOnClickListener(v->{scopeExpanded=!scopeExpanded;refresh();});
  scopePanel=new LinearLayout(context);scopePanel.setOrientation(VERTICAL);scopePanel.setTag("backupScopePanel");addView(scopePanel,new LayoutParams(-1,-2));
  TextView intro=new TextView(context);intro.setText("请选择确切范围。不同模块分别保存；已完成项不会因后项失败自动撤回。人工龙头仅合并新增。完整文件最多32 MiB，单项最多8 MiB，人工配置最多2 MiB。");scopePanel.addView(intro);scopeNotes.add(intro);
  JSONArray catalog=coordinator.catalog();for(int i=0;i<catalog.length();i++){JSONObject d=catalog.getJSONObject(i);String label=d.getString("label"),noteText=d.getString("scope")+"\n"+d.getString("reason");names.put(d.getString("id"),label);CheckBox box=new CheckBox(context);box.setText(label+(d.getBoolean("exportReady")?"":"（不可用）"));box.setTextSize(16);box.setMinHeight(dp(48));box.setContentDescription(label+"\n"+noteText);box.setTag(d.getString("id"));choices.add(box);exportable.put(d.getString("id"),d.getBoolean("exportReady"));scopePanel.addView(box,new LayoutParams(-1,-2));TextView note=new TextView(context);note.setText(noteText);note.setTextSize(14);scopePanel.addView(note,new LayoutParams(-1,-2));scopeNotes.add(note);}
  notesToggle=button("展开范围与限制说明","toggleBackupNotes");scopePanel.addView(notesToggle,new LayoutParams(-1,-2));notesToggle.setOnClickListener(v->{notesExpanded=!notesExpanded;refresh();});
  generate=button("生成所选备份","exportBackup");open=button("选择备份文件","openBackup");preview=button("校验并预览","previewBackup");cancel=button("取消本次预览","cancelBackup");begin=button("备份当前数据并开始","beginBackup");begin.setContentDescription("保存恢复前备份并开始");next=button("执行下一项","nextBackup");stop=button("停止后续项","stopBackup");reread=button("重读保存的回执","readReceipt");
  otherActionsToggle=button("其他操作","toggleBackupActions");addView(otherActionsToggle,new LayoutParams(-1,-2));secondaryActions=new LinearLayout(context);secondaryActions.setOrientation(VERTICAL);secondaryActions.setTag("backupOtherActions");addView(secondaryActions,new LayoutParams(-1,-2));otherActionsToggle.setOnClickListener(v->{otherActionsExpanded=!otherActionsExpanded;refresh();});
  details=new TextView(context);details.setTag("backupDetails");details.setTextIsSelectable(true);details.setTextSize(14);details.setLineSpacing(dp(2),1f);details.setPadding(0,dp(8),0,dp(8));addView(details,new LayoutParams(-1,-2));
  ack=new CheckBox(context);ack.setText("已核对逐项差异；理解各项分别保存，失败后需重新核对");ack.setMinHeight(dp(48));ack.setTag("ackBackup");addView(ack,new LayoutParams(-1,-2));ack.setOnCheckedChangeListener((v,on)->refresh());
  actionDock=new LinearLayout(context);actionDock.setOrientation(VERTICAL);actionDock.setTag("backupActionDock");addView(actionDock,new LayoutParams(-1,-2));primaryActions=new LinearLayout(context);primaryActions.setTag("backupPrimaryActions");actionDock.addView(primaryActions,new LayoutParams(-1,-2));
  LinearLayout paging=new LinearLayout(context);paging.setTag("backupPaging");actionDock.addView(paging,new LayoutParams(-1,-2));previousText=button("上一段","previousPreviewText");nextText=button("下一段","nextPreviewText");paging.addView(previousText,new LayoutParams(0,-2,1));paging.addView(nextText,new LayoutParams(0,-2,1));previousText.setOnClickListener(v->{textOffset=Math.max(0,textOffset-32768);renderText();revealDetails();});nextText.setOnClickListener(v->{textOffset+=32768;renderText();revealDetails();});
  for(CheckBox box:choices)box.setOnCheckedChangeListener((v,on)->cancelPreview());
  generate.setOnClickListener(v->{JSONArray ids=selected();byte[][] prepared={null};run(false,containsGroup(ids),()->{JSONObject b=coordinator.exportSelected(ids,Instant.now().toString());prepared[0]=encode(b);JSONObject summary=UnifiedBackupFiles.summary(prepared[0]);return summary.put("display",UnifiedBackupFiles.previewText(summary));},summary->{export.receive(prepared[0],summary);collapseScope();showText("已生成所选备份，尚未写入文件。\n完整性校验："+summary.getString("sha256"));});});
  open.setOnClickListener(v->{try{picker.run();}catch(Exception e){details.setText(e.getMessage());}});
  preview.setOnClickListener(v->{JSONObject b=bundle;JSONArray ids=selected();String id=UUID.randomUUID().toString();Map<String,String> labels=new HashMap<>(names);run(false,containsGroup(ids),()->{JSONObject p=coordinator.prepareImport(b,ids,id,Instant.now().toString());return object("payload",p,"display",planText(p,labels));},result->{plan=result.getJSONObject("payload");ack.setChecked(false);collapseScope();showText(result.getString("display"));revealDetails();});});
  cancel.setOnClickListener(v->cancelPreview());
  begin.setOnClickListener(v->{if(!active||closed||!isShown()||!v.isEnabled()||!ack.isChecked())return;JSONObject p=plan;run(true,containsGroup(p.optJSONArray("selectedDomainIds")),()->{JSONObject op=coordinator.begin(p,true);return object("payload",op,"display",receiptText(op));},result->{started=true;canContinue=true;showText(result.getString("display"));});});
  next.setOnClickListener(v->run(true,containsGroup(plan.optJSONArray("selectedDomainIds")),()->{JSONObject op=coordinator.step();return object("payload",op,"display",receiptText(op));},result->{JSONObject op=result.getJSONObject("payload");canContinue=Arrays.asList("ready","running").contains(op.optString("state"));showText(result.getString("display"));}));
  stop.setOnClickListener(v->run(true,false,()->{JSONObject op=coordinator.stop();return object("display",receiptText(op));},result->{canContinue=false;showText(result.getString("display"));}));
  reread.setOnClickListener(v->run(false,true,()->{JSONObject result=coordinator.rereadReceipt(),r=result.getJSONObject("receipt");StringBuilder text=new StringBuilder(receiptText(r));JSONArray os=result.getJSONArray("observations");for(int i=0;i<os.length();i++){JSONObject o=os.getJSONObject(i);text.append("\n").append(UnifiedBackupFiles.domainName(o.getString("id"))).append("：结果未确认；").append(observation(o.getString("observation")));}return object("state",r.optString("state"),"display",text.toString());},result->{if(!Arrays.asList("ready","running").contains(result.optString("state")))canContinue=false;showText(result.getString("display"));}));
  showText("尚未读取数据。");refresh();
 }
 int dp(int value){return Math.round(value*getResources().getDisplayMetrics().density);}
 Button button(String title,String id){Button b=new Button(getContext());b.setText(title);b.setTag(id);b.setTextSize(14);b.setAllCaps(false);b.setMinHeight(dp(48));b.setMinWidth(0);b.setMinimumWidth(0);b.setPadding(dp(8),dp(4),dp(8),dp(4));return b;}
 void arrangeActions(){
  Button[] all={generate,open,preview,cancel,begin,next,stop,reread};List<Button> primary=writing?Collections.emptyList():started?(canContinue?Arrays.asList(next,stop):Arrays.asList(reread)):busy?Arrays.asList(cancel):plan.length()>0?Arrays.asList(begin,cancel):bundle.length()>0?Arrays.asList(preview,cancel):Arrays.asList(generate,open);
  for(Button b:all)if(b.getParent() instanceof android.view.ViewGroup)((android.view.ViewGroup)b.getParent()).removeView(b);
  primaryActions.removeAllViews();secondaryActions.removeAllViews();for(Button b:primary)primaryActions.addView(b,new LayoutParams(0,-2,1));primaryActions.setVisibility(primary.isEmpty()?GONE:VISIBLE);
  LinearLayout row=null;int i=0;for(Button b:all)if(!primary.contains(b)){if(i++%2==0){row=new LinearLayout(getContext());secondaryActions.addView(row,new LayoutParams(-1,-2));}row.addView(b,new LayoutParams(0,-2,1));}
  secondaryActions.setVisibility(otherActionsExpanded?VISIBLE:GONE);otherActionsToggle.setText(otherActionsExpanded?"收起其他操作":"其他操作");
  scopePanel.setVisibility(scopeExpanded?VISIBLE:GONE);scopeToggle.setText("选择范围 · 已选 "+selected().length()+" 项 · "+(scopeExpanded?"收起":"展开"));for(TextView note:scopeNotes)note.setVisibility(notesExpanded?VISIBLE:GONE);notesToggle.setText(notesExpanded?"收起范围与限制说明":"展开范围与限制说明");
  updateStage();ack.setVisibility(plan.length()>0||started?VISIBLE:GONE);
 }
 void updateStage(){stage.setText(writing?"正在写入，请等待回执":started?"4  执行与回执":plan.length()>0?"3  核对恢复预览":bundle.length()>0?"2  校验并预览":"1  选择范围");}
 void collapseScope(){scopeExpanded=false;otherActionsExpanded=false;refresh();}
 void revealDetails(){details.post(()->{if(!closed&&active&&details.isShown())details.requestRectangleOnScreen(new android.graphics.Rect(0,0,details.getWidth(),Math.min(details.getHeight(),dp(96))),true);});}
 JSONArray selected(){JSONArray ids=new JSONArray();for(CheckBox b:choices)if(b.isChecked())ids.put(b.getTag());return ids;}
 void refresh(){if(ack==null||details==null)return;boolean idle=active&&!closed&&!busy&&runner!=null,has=selected().length()>0,ok=has;for(CheckBox b:choices){if(b.isChecked())ok&=Boolean.TRUE.equals(exportable.get((String)b.getTag()));b.setEnabled(active&&!closed&&!writing&&!started);}generate.setEnabled(idle&&!started&&ok&&export!=null);open.setEnabled(idle&&!started&&picker!=null);preview.setEnabled(idle&&!started&&has&&bundle.length()>0);cancel.setEnabled(active&&!closed&&!writing&&!started&&(busy||plan.length()>0||bundle.length()>0));ack.setEnabled(idle&&!started&&plan.optBoolean("canConfirm"));begin.setEnabled(idle&&!started&&ack.isChecked()&&plan.optBoolean("canConfirm")&&coordinator.canJournal());next.setEnabled(idle&&started&&canContinue);stop.setEnabled(idle&&started&&canContinue);reread.setEnabled(idle&&coordinator.canJournal());arrangeActions();onPresentationChanged.run();}
 void run(boolean isWrite,boolean needsInputs,Read work,Result done){if(busy||closed||!active)return;if(!isWrite)onInvalidate.run();busy=true;writing=isWrite;if(writing)showText("正在写入并核验回执；离开或取消不会撤销已开始的操作。");refresh();WeakReference<UnifiedBackupScreen> ref=new WeakReference<>(this);UnifiedBackupAsyncLane.Done finish=(value,error)->{UnifiedBackupScreen view=ref.get();if(view==null||view.closed)return;view.busy=false;view.writing=false;if(error!=null){view.plan=new JSONObject();view.ack.setChecked(false);view.canContinue=false;view.showText("操作未确认："+error.getMessage()+"\n不会自动重试；已开始写入的结果请查回执。");}else try{done.accept(value);}catch(Exception e){view.canContinue=false;view.showText(e.getMessage());}view.refresh();};try{runner.run(isWrite,needsInputs,work,finish);onPresentationChanged.run();}catch(Exception e){finish.finish(null,e);}}
 /** Ownership transfer; root file/SAF path uses acceptPrepared instead. Never put full text in saved state. */
 public void acceptBytes(byte[] owned){if(started||busy||closed||!active)return;plan=new JSONObject();bundle=new JSONObject();ack.setChecked(false);run(false,false,()->{JSONObject b=decode(owned);return object("payload",b,"display",importText(b));},r->acceptPrepared(r.getJSONObject("payload"),r.getString("display")));}
 public boolean startImport(){if(started||busy||closed||!active)return false;lane.invalidate();onInvalidate.run();bundle=new JSONObject();plan=new JSONObject();ack.setChecked(false);showText("正在读取所选文件；旧预览已失效。");refresh();return true;}
 public void acceptPrepared(JSONObject value,String summary){if(started||closed||!active)return;bundle=value;plan=new JSONObject();ack.setChecked(false);collapseScope();showText(summary);refresh();revealDetails();}
 static boolean containsGroup(JSONArray ids){if(ids==null)return false;for(int i=0;i<ids.length();i++)if("watchlist-config".equals(ids.optString(i)))return true;return false;}
 static String importText(JSONObject b)throws Exception{List<String> ids=new ArrayList<>();JSONArray selected=b.getJSONArray("selectedDomainIds");for(int i=0;i<selected.length();i++)ids.add(UnifiedBackupFiles.domainName(selected.getString(i)));return "文件校验通过，尚未恢复。\n来源版本："+b.getString("producerVersion")+"\n备份时点："+b.getString("createdAt")+"\n包含："+String.join("、",ids)+"\n请选择要恢复的项后预览；仅归档项无法恢复。";}
 public void cancelPreview(){if(writing){showText("写入已开始；取消不会回滚。请等待并核对回执。");return;}lane.invalidate();onInvalidate.run();if(!started)plan=new JSONObject();ack.setChecked(false);showText(busy?"预览已取消，等待后台释放资源；晚到结果不会接受。":"已取消预览；未开始写入。");refresh();}
 public void setActive(boolean value){active=value;lane.setActive(value);if(!value)onInvalidate.run();if(!value&&!writing&&!started){plan=new JSONObject();ack.setChecked(false);}refresh();}
 void showReceiptInspection(String text){if(closed||!active||busy)return;if(!started){plan=new JSONObject();ack.setChecked(false);}showText(text);refresh();}
 void showText(String text){fullText=text==null?"":text;textOffset=0;renderText();}
 void renderText(){if(textOffset>=fullText.length())textOffset=0;int end=Math.min(fullText.length(),textOffset+32768);details.setText(fullText.substring(textOffset,end));details.setContentDescription("完整文本共 "+fullText.length()+" 字符；当前 "+(textOffset+1)+" 至 "+end+"，分段显示，不截断原文");previousText.setEnabled(textOffset>0);nextText.setEnabled(end<fullText.length());((android.view.View)previousText.getParent()).setVisibility(fullText.length()>32768?VISIBLE:GONE);}
 public void dispose(){closed=true;lane.invalidate();refresh();}
 String name(String id){return names.containsKey(id)?names.get(id):id;}
 String domainNames(JSONArray ids)throws Exception{List<String> labels=new ArrayList<>();for(int i=0;i<ids.length();i++)labels.add(name(ids.getString(i)));return String.join("、",labels);}
 static String observation(String s){switch(s){case"baseline-observed":return"当前仍与开始时一致，提交归属未确认";case"target-observed-unattributed":return"当前与目标相符，但缺可归属的提交回执";case"different-current-state":return"当前数据另有变化，未覆盖或回滚";default:return s;}}
 static String label(String s){switch(s){case"blocked":return"不可恢复";case"ready":return"等待确认";case"pending":return"尚未执行";case"running":return"可继续下一域";case"applying":return"提交结果待核实";case"uncertain":return"结果未确认，已停止";case"failed":return"失败，已停止";case"completed":return"已完成";case"complete":return"本次所选域已完成";case"unchanged":return"无变更";case"stopped":return"已停止";default:return s;}}
 static String planText(JSONObject p,Map<String,String> names)throws Exception{
  StringBuilder out=new StringBuilder("逐项预览 · "+p.getString("operationId")+"\n确认后先保存恢复前备份，再逐项执行。\n");if(!p.getBoolean("journalReady"))out.append("回执保存尚未接入，确认禁用。\n");JSONArray rows=p.getJSONArray("domains");
  for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);out.append("\n").append(names.getOrDefault(r.getString("id"),r.getString("id"))).append("：").append(label(r.getString("state"))).append("\n").append(r.optString("reason",""));out.append(RecentRestore.describeOperationRow(r)).append(SectorObservationRestore.describeOperationRow(r)).append(BusinessRestore.describeOperationRow(r)).append(CandidateRestore.describe(r)).append(IndustryArchiveReading.describeOperationRow(r));JSONObject token=r.optJSONObject("preview"),owner=token==null?null:token.optJSONObject("owner");if(owner==null)continue;if(owner.has("change"))out.append(WatchlistWorkspaceModel.describe(owner.getJSONObject("change")));else if(owner.has("addedBoards")){out.append("\n新增板块 ").append(owner.getInt("addedBoards")).append("，新增候选 ").append(owner.getInt("addedLeaders")).append("，身份待核对 ").append(owner.getInt("unresolvedCount")).append("\n");JSONArray conflicts=owner.getJSONArray("conflicts");for(int j=0;j<conflicts.length();j++)out.append(conflicts.getString(j)).append("\n");JSONArray boards=owner.getJSONObject("config").getJSONArray("sectors");for(int j=0;j<boards.length();j++){JSONObject b=boards.getJSONObject(j);out.append("合并后板块：").append(b.getString("name")).append(" · ").append(b.optString("description","")).append("\n");JSONArray ls=b.getJSONArray("leaders");for(int k=0;k<ls.length();k++){JSONObject l=ls.getJSONObject(k);out.append(l.getString("name")).append(" ").append(l.getString("code")).append(" ").append(l.isNull("fullId")?"":l.getString("fullId")).append(" ").append(l.getString("role")).append(" · 权重 ").append(l.get("weight")).append("\n").append(l.optString("reason","")).append(" ").append(l.optString("note","")).append("\n");}}}}
  return out.toString();
 }
 static String receiptText(JSONObject op)throws Exception{if(op.length()==0)return "没有已保存的操作回执。";StringBuilder out=new StringBuilder("本次操作："+label(op.getString("state"))+"\n不同模块分别提交。恢复前备份与逐项状态保存在操作回执中。\n");if(op.has("journalError"))out.append("回执保存失败：").append(op.getString("journalError")).append("\n此结果未持久保存，必须重读；禁止继续。\n");JSONArray rows=op.optJSONArray("domains");if(rows!=null)for(int i=0;i<rows.length();i++){JSONObject r=rows.getJSONObject(i);out.append(r.getString("id")).append("：").append(label(r.getString("state"))).append(" ").append(r.optString("reason","")).append("\n").append(RecentRestore.describeOperationRow(r)).append(SectorObservationRestore.describeOperationRow(r)).append(BusinessRestore.describeOperationRow(r)).append(CandidateRestore.describe(r)).append(IndustryArchiveReading.describeOperationRow(r));}return out.toString();}
}
